import pandas as pd
import numpy as np

TARGET_COLUMN = 'target'


class DecisionTree:
    def __init__(self, max_depth=10, min_samples_split=5, min_samples_leaf=2,
                 max_features=None, random_state=None):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.max_features = max_features
        self.rng = np.random.RandomState(random_state)
        self.tree = None

    def _gini(self, y):
        if len(y) == 0:
            return 0.0
        p = np.mean(y)
        return 2 * p * (1 - p)

    def _best_split(self, X, y):
        n, d = X.shape
        best_gain = -1
        best_feat = None
        best_thresh = None

        parent_gini = self._gini(y)

        if self.max_features is not None:
            features = self.rng.choice(d, min(self.max_features, d), replace=False)
        else:
            features = np.arange(d)

        for feat in features:
            vals = X[:, feat]
            thresholds = np.unique(np.percentile(vals, np.arange(10, 100, 10)))
            for thresh in thresholds:
                left_mask = vals <= thresh
                right_mask = ~left_mask
                n_left = left_mask.sum()
                n_right = right_mask.sum()
                if n_left < self.min_samples_leaf or n_right < self.min_samples_leaf:
                    continue
                gain = parent_gini - (n_left * self._gini(y[left_mask]) + n_right * self._gini(y[right_mask])) / n
                if gain > best_gain:
                    best_gain = gain
                    best_feat = feat
                    best_thresh = thresh

        return best_feat, best_thresh, best_gain

    def _build(self, X, y, depth):
        n = len(y)
        if depth >= self.max_depth or n < self.min_samples_split or len(np.unique(y)) == 1:
            return {'leaf': True, 'value': int(np.round(np.mean(y)))}

        feat, thresh, gain = self._best_split(X, y)
        if feat is None or gain <= 0:
            return {'leaf': True, 'value': int(np.round(np.mean(y)))}

        left_mask = X[:, feat] <= thresh
        return {
            'leaf': False,
            'feat': feat,
            'thresh': thresh,
            'left': self._build(X[left_mask], y[left_mask], depth + 1),
            'right': self._build(X[~left_mask], y[~left_mask], depth + 1),
        }

    def fit(self, X, y):
        self.tree = self._build(X, y, 0)
        return self

    def _predict_one(self, x, node):
        if node['leaf']:
            return node['value']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])


class RandomForest:
    def __init__(self, n_trees=100, max_depth=15, min_samples_split=5,
                 min_samples_leaf=2, max_features='sqrt', random_state=42):
        self.n_trees = n_trees
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.max_features = max_features
        self.random_state = random_state
        self.trees = []

    def fit(self, X, y):
        n, d = X.shape
        if self.max_features == 'sqrt':
            mf = int(np.sqrt(d))
        elif self.max_features is None:
            mf = d
        else:
            mf = self.max_features

        rng = np.random.RandomState(self.random_state)
        self.trees = []
        for i in range(self.n_trees):
            idx = rng.choice(n, n, replace=True)
            tree = DecisionTree(
                max_depth=self.max_depth,
                min_samples_split=self.min_samples_split,
                min_samples_leaf=self.min_samples_leaf,
                max_features=mf,
                random_state=rng.randint(0, 2**31),
            )
            tree.fit(X[idx], y[idx])
            self.trees.append(tree)
        return self

    def predict(self, X):
        preds = np.array([t.predict(X) for t in self.trees])
        return (preds.mean(axis=0) >= 0.5).astype(int)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Random forest classifier."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values.astype(np.float64)
    y_train = train[TARGET_COLUMN].values.astype(np.float64)
    X_test = test[feature_cols].values.astype(np.float64)

    rf = RandomForest(n_trees=50, max_depth=12, random_state=42)
    rf.fit(X_train, y_train)
    preds = rf.predict(X_test)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)

